/* ============================================================
   NEON OVERDRIVE — interface styling
   ============================================================ */

@font-face {
  font-family: 'Orbitron';
  src: url('./assets/fonts/orbitron.woff2') format('woff2');
  font-weight: 400 900;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('./assets/fonts/rajdhani-500.woff2') format('woff2');
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('./assets/fonts/rajdhani-600.woff2') format('woff2');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('./assets/fonts/rajdhani-700.woff2') format('woff2');
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

:root {
  --bg: #05010f;
  --ink: #dffcff;
  --muted: #7f9fb8;
  --cyan: #31f2ff;
  --cyan-hot: #b9feff;
  --magenta: #ff2bcc;
  --magenta-soft: #ff8ae8;
  --violet: #9d5cff;
  --amber: #ffc45c;
  --danger: #ff3d6e;
  --lime: #b8ff4a;
  --panel: rgba(7, 3, 22, 0.78);
  --line: rgba(70, 240, 255, 0.28);
  --font-ui: 'Rajdhani', 'Trebuchet MS', sans-serif;
  --font-display: 'Orbitron', 'Arial Black', sans-serif;
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-top: env(safe-area-inset-top, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: var(--bg);
  overflow: hidden;
  overscroll-behavior: none;
}

body {
  color: var(--ink);
  font-family: var(--font-ui);
  font-weight: 600;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
}

#game-root {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: #04010c;
  isolation: isolate;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
  cursor: default;
}

body[data-state="playing"] #game { cursor: ew-resize; }

/* ============================================================
   Full-screen atmosphere effects
   ============================================================ */

#fx-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 20;
}

.screen-vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 82% 72% at 50% 48%, transparent 42%, rgba(2, 0, 8, 0.5) 78%, rgba(2, 0, 8, 0.88) 100%),
    linear-gradient(to bottom, rgba(2, 0, 8, 0.32), transparent 16%, transparent 82%, rgba(2, 0, 8, 0.52));
  mix-blend-mode: multiply;
}

.scanlines {
  position: absolute;
  inset: 0;
  opacity: 0.16;
  background: repeating-linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.055) 0px,
    rgba(255, 255, 255, 0.055) 1px,
    transparent 1px,
    transparent 3px
  );
  mix-blend-mode: overlay;
}

.edge-glow {
  position: absolute;
  inset: 0;
  box-shadow:
    inset 0 0 90px rgba(49, 242, 255, 0.08),
    inset 0 0 220px rgba(157, 92, 255, 0.05);
}

.nitro-fx {
  position: absolute;
  inset: 0;
  opacity: 0;
  background:
    radial-gradient(ellipse 58% 70% at 50% 54%, transparent 38%, rgba(49, 242, 255, 0.12) 78%, rgba(49, 242, 255, 0.22) 100%),
    linear-gradient(90deg, rgba(255, 43, 204, 0.08), transparent 18%, transparent 82%, rgba(49, 242, 255, 0.08));
  box-shadow: inset 0 0 110px rgba(49, 242, 255, 0.24);
  mix-blend-mode: screen;
  will-change: opacity;
}

.hit-fx {
  position: absolute;
  inset: 0;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 30%, rgba(255, 61, 110, 0.44) 100%);
  mix-blend-mode: screen;
  will-change: opacity;
}

.boot-flash {
  position: absolute;
  inset: 0;
  z-index: 80;
  pointer-events: none;
  background: #d9fdff;
  opacity: 0;
}
.boot-flash.fire { animation: bootFlash 700ms ease-out forwards; }
@keyframes bootFlash {
  0% { opacity: 0.94; }
  28% { opacity: 0.42; }
  100% { opacity: 0; }
}

/* ============================================================
   HUD
   ============================================================ */

.hud {
  position: absolute;
  inset: 0;
  z-index: 30;
  padding: calc(20px + var(--safe-top)) clamp(18px, 3vw, 46px) calc(18px + var(--safe-bottom));
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  pointer-events: none;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 260ms ease, transform 320ms cubic-bezier(.2, .8, .2, 1);
}
body[data-state="playing"] .hud,
body[data-state="paused"] .hud,
body[data-state="dying"] .hud {
  opacity: 1;
  transform: none;
}
body[data-state="dying"] .hud { opacity: 0.55; }

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.hud-block { min-width: 160px; }

.hud-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-display);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.24em;
  color: rgba(185, 254, 255, 0.66);
  text-shadow: 0 0 14px rgba(49, 242, 255, 0.55);
}
.label-dot {
  width: 5px;
  height: 5px;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
  transform: rotate(45deg);
}

.hud-score {
  margin-top: 4px;
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(22px, 2.4vw, 34px);
  line-height: 1;
  letter-spacing: 0.06em;
  color: #ecffff;
  text-shadow:
    0 0 8px rgba(49, 242, 255, 0.85),
    0 0 26px rgba(49, 242, 255, 0.45),
    0 2px 0 rgba(0, 0, 0, 0.35);
  font-variant-numeric: tabular-nums;
}
.hud-best {
  margin-top: 6px;
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.22em;
  color: rgba(255, 138, 232, 0.72);
}
.hud-best span { color: var(--magenta-soft); text-shadow: 0 0 10px rgba(255, 43, 204, 0.6); }

.combo {
  position: absolute;
  top: calc(18px + var(--safe-top));
  left: 50%;
  transform: translate(-50%, -4px);
  width: min(210px, 32vw);
  text-align: center;
  opacity: 0;
  transition: opacity 200ms ease, transform 260ms ease;
}
.combo.active { opacity: 1; transform: translate(-50%, 0); }
.combo-top { display: flex; align-items: baseline; justify-content: center; gap: 7px; }
.combo-x {
  font-family: var(--font-display);
  font-size: clamp(18px, 2vw, 26px);
  font-weight: 900;
  font-style: italic;
  letter-spacing: 0.02em;
  color: var(--amber);
  text-shadow: 0 0 12px rgba(255, 196, 92, 0.8), 0 0 34px rgba(255, 140, 20, 0.35);
}
.combo-label {
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.28em;
  color: rgba(255, 214, 150, 0.66);
}
.combo-bar {
  position: relative;
  height: 3px;
  margin: 4px auto 0;
  width: 100%;
  background: rgba(255, 196, 92, 0.12);
  clip-path: polygon(4px 0, 100% 0, calc(100% - 4px) 100%, 0 100%);
  overflow: hidden;
}
.combo-bar i {
  display: block;
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, var(--magenta), var(--amber));
  box-shadow: 0 0 12px rgba(255, 196, 92, 0.8);
  transform-origin: left center;
}

.hud-right {
  display: flex;
  align-items: center;
  gap: 10px;
  pointer-events: auto;
}

.sector-chip {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 12px;
  margin-right: 2px;
  background: linear-gradient(180deg, rgba(43, 16, 82, 0.62), rgba(7, 3, 22, 0.55));
  border: 1px solid rgba(157, 92, 255, 0.34);
  clip-path: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px);
}
.sector-chip span {
  font-family: var(--font-display);
  font-size: 8px;
  letter-spacing: 0.18em;
  color: rgba(190, 168, 255, 0.66);
}
.sector-chip b {
  font-family: var(--font-display);
  font-size: 14px;
  color: var(--magenta-soft);
  text-shadow: 0 0 10px rgba(255, 43, 204, 0.7);
}

.icon-btn {
  width: 40px;
  height: 34px;
  display: grid;
  place-items: center;
  color: var(--cyan-hot);
  background: linear-gradient(180deg, rgba(17, 28, 56, 0.66), rgba(7, 3, 22, 0.58));
  border: 1px solid rgba(49, 242, 255, 0.3);
  clip-path: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px);
  transition: border-color 160ms ease, box-shadow 160ms ease, color 160ms ease;
}
.icon-btn:hover {
  border-color: rgba(49, 242, 255, 0.85);
  box-shadow: 0 0 20px rgba(49, 242, 255, 0.26), inset 0 0 14px rgba(49, 242, 255, 0.14);
}
.icon-btn svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.icon-btn svg path:first-child { fill: currentColor; stroke: none; }
.icon-btn .icon-muted { display: none; }
.muted .icon-sound { display: none; }
.muted .icon-muted { display: block; }
.muted { color: rgba(255, 120, 160, 0.82); border-color: rgba(255, 61, 110, 0.34); }

.hud-bottom {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 18px;
}

.hull-block { justify-self: start; width: min(250px, 26vw); }
.hull-bars { display: flex; gap: 6px; margin-top: 7px; }
.hull-bars i {
  position: relative;
  height: 11px;
  flex: 1;
  background: linear-gradient(180deg, rgba(184, 255, 74, 0.95), rgba(38, 148, 78, 0.55));
  border: 1px solid rgba(184, 255, 74, 0.55);
  box-shadow: 0 0 12px rgba(184, 255, 74, 0.35), inset 0 0 7px rgba(255, 255, 255, 0.25);
  transform: skewX(-18deg);
  transition: background 240ms ease, opacity 240ms ease, box-shadow 240ms ease;
}
.hull-bars i:nth-child(2) { transition-delay: 25ms; }
.hull-bars i:nth-child(3) { transition-delay: 50ms; }
.hull-bars i.down {
  background: linear-gradient(180deg, rgba(120, 37, 66, 0.5), rgba(38, 10, 30, 0.4));
  border-color: rgba(255, 61, 110, 0.26);
  box-shadow: none;
  opacity: 0.6;
}
.hud-sub {
  margin-top: 7px;
  font-family: var(--font-display);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: rgba(154, 190, 208, 0.52);
}
.hull-block.damaged .hud-sub { color: var(--danger); text-shadow: 0 0 10px rgba(255, 61, 110, 0.6); }

.speed-block {
  justify-self: center;
  text-align: center;
  padding-bottom: 2px;
  filter: drop-shadow(0 0 18px rgba(49, 242, 255, 0.28));
}
.speed-readout {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 7px;
  line-height: 0.82;
}
.speed-readout span {
  font-family: var(--font-display);
  font-weight: 900;
  font-style: italic;
  font-size: clamp(34px, 4.8vw, 68px);
  letter-spacing: -0.02em;
  color: #f0ffff;
  text-shadow: 0 0 10px rgba(49, 242, 255, 0.75), 0 0 40px rgba(49, 242, 255, 0.35);
  font-variant-numeric: tabular-nums;
}
.speed-readout em {
  font-family: var(--font-display);
  font-style: normal;
  font-size: 9px;
  letter-spacing: 0.15em;
  color: rgba(185, 254, 255, 0.62);
}
.distance-readout {
  margin-top: 7px;
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.24em;
  color: rgba(255, 138, 232, 0.72);
}
.distance-readout span { color: var(--magenta-soft); font-size: 12px; }

.nitro-block { justify-self: end; width: min(260px, 28vw); }
.nitro-head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.18em;
  color: rgba(185, 254, 255, 0.66);
}
.nitro-head b { color: var(--cyan-hot); font-weight: 700; }
.nitro-bar {
  position: relative;
  height: 12px;
  margin-top: 7px;
  background: rgba(9, 15, 35, 0.85);
  border: 1px solid rgba(49, 242, 255, 0.34);
  box-shadow: inset 0 0 10px rgba(0, 0, 0, 0.7);
  overflow: hidden;
  clip-path: polygon(6px 0, 100% 0, calc(100% - 6px) 100%, 0 100%);
}
.nitro-bar > i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  background:
    linear-gradient(90deg, rgba(49, 242, 255, 0.94), rgba(157, 92, 255, 0.95) 60%, rgba(255, 43, 204, 0.95));
  box-shadow: 0 0 15px rgba(49, 242, 255, 0.65), inset 0 0 10px rgba(255, 255, 255, 0.35);
  transition: filter 140ms linear;
}
.nitro-bar.burning > i {
  animation: nitroPulse 320ms ease-in-out infinite alternate;
}
@keyframes nitroPulse {
  from { filter: brightness(1) saturate(1); }
  to { filter: brightness(1.55) saturate(1.15); }
}
.nitro-ticks {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 22px, rgba(3, 0, 12, 0.55) 22px 24px);
  pointer-events: none;
}
.nitro-block.burning .hud-sub { color: var(--cyan); text-shadow: 0 0 12px rgba(49, 242, 255, 0.7); }

/* ============================================================
   Screens & panels
   ============================================================ */

#screens {
  position: absolute;
  inset: 0;
  z-index: 40;
  pointer-events: none;
}

.screen {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: clamp(18px, 4vh, 48px) clamp(16px, 5vw, 72px);
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 320ms ease, visibility 0s linear 320ms;
}
.screen.active {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transition: opacity 320ms ease, visibility 0s linear 0s;
}

#screen-menu {
  justify-content: flex-start;
  background:
    radial-gradient(ellipse 64% 52% at 50% 38%, rgba(18, 4, 48, 0.18), transparent 70%),
    linear-gradient(to bottom, rgba(4, 1, 12, 0.6) 0%, rgba(4, 1, 12, 0.14) 34%, rgba(4, 1, 12, 0.04) 58%, rgba(4, 1, 12, 0.72) 100%);
  padding-top: clamp(28px, 7vh, 84px);
}
#screen-menu::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse 85% 65% at 50% 55%, transparent 55%, rgba(3, 0, 11, 0.45));
}

.menu-skyline-fade {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 56%;
  pointer-events: none;
  background: linear-gradient(to bottom, transparent 0%, rgba(6, 1, 18, 0.12) 55%, rgba(4, 0, 12, 0.72) 100%);
}

.menu-content {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: min(780px, 100%);
  text-align: center;
}

.screen.active .menu-content > * {
  animation: menuRise 680ms cubic-bezier(.16, .84, .28, 1) both;
}
.screen.active .menu-content > :nth-child(1) { animation-delay: 40ms; }
.screen.active .menu-content > :nth-child(2) { animation-delay: 100ms; }
.screen.active .menu-content > :nth-child(3) { animation-delay: 160ms; }
.screen.active .menu-content > :nth-child(4) { animation-delay: 240ms; }
@keyframes menuRise {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: translateY(0); }
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--font-display);
  font-size: clamp(8px, 0.78vw, 11px);
  font-weight: 700;
  letter-spacing: 0.42em;
  color: rgba(185, 254, 255, 0.68);
  text-shadow: 0 0 12px rgba(49, 242, 255, 0.5);
  text-transform: uppercase;
}
.eyebrow-line {
  display: block;
  width: clamp(22px, 5vw, 74px);
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(49, 242, 255, 0.8));
  box-shadow: 0 0 8px rgba(49, 242, 255, 0.55);
}
.eyebrow .eyebrow-line:last-child {
  background: linear-gradient(90deg, rgba(49, 242, 255, 0.8), transparent);
}
.eyebrow-slash { color: var(--magenta); text-shadow: 0 0 10px var(--magenta); }
.eyebrow.small { font-size: 9px; letter-spacing: 0.3em; justify-content: center; }
.eyebrow.danger { color: rgba(255, 115, 145, 0.82); text-shadow: 0 0 12px rgba(255, 61, 110, 0.55); }
.eyebrow.danger .eyebrow-line { background: linear-gradient(90deg, transparent, rgba(255, 61, 110, 0.7)); }

.logo {
  position: relative;
  margin: clamp(14px, 2.2vh, 26px) 0 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  font-family: var(--font-display);
  font-weight: 900;
  line-height: 0.82;
  transform: skewX(-5deg);
  filter: drop-shadow(0 20px 42px rgba(0, 0, 0, 0.6));
}
.logo-top {
  position: relative;
  font-size: clamp(18px, 2.4vw, 34px);
  letter-spacing: 0.72em;
  padding-left: 0.72em;
  color: #e7feff;
  text-shadow:
    0 0 6px rgba(255, 255, 255, 0.9),
    0 0 22px rgba(49, 242, 255, 0.85),
    0 0 54px rgba(49, 242, 255, 0.4);
}
.logo-accent { color: var(--magenta); text-shadow: 0 0 8px rgba(255, 43, 204, 0.9), 0 0 38px rgba(255, 43, 204, 0.5); }
.logo-main {
  position: relative;
  display: block;
  margin-top: 0.1em;
  font-size: clamp(42px, 8.6vw, 120px);
  letter-spacing: 0.015em;
  line-height: 0.86;
  color: transparent;
  background: linear-gradient(178deg, #ffffff 0%, #d9fbff 18%, #33e6ff 44%, #b15cff 68%, #ff2bcc 90%, #ff9ae9 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-stroke: 1.5px rgba(255, 255, 255, 0.28);
  filter: drop-shadow(0 0 22px rgba(49, 242, 255, 0.48)) drop-shadow(0 0 58px rgba(255, 43, 204, 0.3));
}
.logo-main::before {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  color: transparent;
  -webkit-text-stroke: 1px rgba(185, 254, 255, 0.38);
  transform: translate(2px, 2px);
  z-index: -1;
  filter: blur(0.4px);
}
.logo-main::after {
  content: '';
  position: absolute;
  left: 8%;
  right: 8%;
  bottom: -0.16em;
  height: 2px;
  background: linear-gradient(90deg, transparent, rgba(49, 242, 255, 0.75), rgba(255, 43, 204, 0.8), transparent);
  box-shadow: 0 0 16px rgba(49, 242, 255, 0.6);
}

.tagline {
  margin: clamp(12px, 1.8vh, 20px) 0 clamp(16px, 2.6vh, 28px);
  font-family: var(--font-display);
  font-size: clamp(8px, 0.9vw, 11px);
  font-weight: 500;
  letter-spacing: 0.36em;
  color: rgba(206, 230, 255, 0.6);
}
.tag-dot { margin: 0 0.7em; color: var(--magenta); text-shadow: 0 0 10px var(--magenta); }

.menu-panel {
  position: relative;
  width: min(470px, 92vw);
  padding: clamp(18px, 2.8vh, 28px) clamp(20px, 3vw, 34px) clamp(16px, 2.4vh, 24px);
  background:
    linear-gradient(150deg, rgba(20, 8, 48, 0.82), rgba(5, 2, 18, 0.72)),
    radial-gradient(ellipse at top, rgba(49, 242, 255, 0.08), transparent 60%);
  border: 1px solid rgba(49, 242, 255, 0.2);
  clip-path: polygon(16px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 16px);
  box-shadow:
    0 28px 80px rgba(0, 0, 0, 0.55),
    inset 0 0 44px rgba(49, 242, 255, 0.045),
    0 0 0 1px rgba(255, 43, 204, 0.05);
  backdrop-filter: blur(10px) saturate(1.1);
  -webkit-backdrop-filter: blur(10px) saturate(1.1);
}
.menu-panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 16px;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, rgba(49, 242, 255, 0.65), rgba(49, 242, 255, 0.06) 55%, transparent);
}
.menu-panel::after {
  content: '';
  position: absolute;
  bottom: 0;
  right: 16px;
  width: 45%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 43, 204, 0.55));
}

.panel-corner {
  position: absolute;
  width: 9px;
  height: 9px;
  border: 1px solid rgba(49, 242, 255, 0.55);
  pointer-events: none;
}
.panel-corner.tl { top: 7px; left: 7px; border-right: 0; border-bottom: 0; }
.panel-corner.tr { top: 7px; right: 7px; border-left: 0; border-bottom: 0; }
.panel-corner.bl { bottom: 7px; left: 7px; border-right: 0; border-top: 0; }
.panel-corner.br { bottom: 7px; right: 7px; border-left: 0; border-top: 0; }

.menu-best {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 14px;
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(49, 242, 255, 0.12);
}
.menu-best-label {
  font-family: var(--font-display);
  font-size: 9px;
  letter-spacing: 0.26em;
  color: rgba(185, 254, 255, 0.55);
}
.menu-best strong {
  font-family: var(--font-display);
  font-size: clamp(18px, 2vw, 24px);
  font-weight: 700;
  color: var(--magenta-soft);
  letter-spacing: 0.08em;
  text-shadow: 0 0 16px rgba(255, 43, 204, 0.55);
  font-variant-numeric: tabular-nums;
}

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 52px;
  padding: 0 24px;
  overflow: hidden;
  font-family: var(--font-display);
  font-size: clamp(11px, 1vw, 14px);
  font-weight: 700;
  letter-spacing: 0.2em;
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
  transition: transform 160ms ease, filter 160ms ease, background 160ms ease;
}
.btn-primary {
  width: 100%;
  color: #041016;
  background:
    linear-gradient(100deg, #8ffcff 0%, #31f2ff 28%, #56c8ff 55%, #ff4bd6 100%);
  box-shadow:
    0 0 26px rgba(49, 242, 255, 0.32),
    0 0 64px rgba(255, 43, 204, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.6);
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.3);
}
.btn-primary::before {
  content: '';
  position: absolute;
  inset: 1px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.26), transparent 52%, rgba(5, 0, 20, 0.1));
  clip-path: polygon(11px 0, 100% 0, 100% calc(100% - 11px), calc(100% - 11px) 100%, 0 100%, 0 11px);
  pointer-events: none;
}
.btn-primary:hover {
  transform: translateY(-2px);
  filter: brightness(1.12) saturate(1.1);
  box-shadow: 0 0 38px rgba(49, 242, 255, 0.5), 0 0 90px rgba(255, 43, 204, 0.24);
}
.btn-primary:active { transform: translateY(1px) scale(0.995); }
.btn-main { position: relative; z-index: 1; }
.btn-key {
  position: relative;
  z-index: 1;
  margin-left: auto;
  padding: 3px 7px;
  font-size: 8px;
  letter-spacing: 0.16em;
  color: rgba(4, 16, 22, 0.72);
  border: 1px solid rgba(4, 16, 22, 0.28);
  background: rgba(255, 255, 255, 0.16);
}
.btn-shine {
  position: absolute;
  top: -60%;
  left: -30%;
  width: 30%;
  height: 220%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.45), transparent);
  transform: skewX(-22deg);
  animation: btnShine 4.2s ease-in-out infinite;
  pointer-events: none;
}
@keyframes btnShine {
  0%, 58% { left: -40%; opacity: 0; }
  62% { opacity: 0.8; }
  82% { left: 130%; opacity: 0.5; }
  100% { left: 130%; opacity: 0; }
}
.btn-ghost {
  min-height: 42px;
  font-size: 10px;
  color: rgba(185, 254, 255, 0.72);
  background: rgba(49, 242, 255, 0.035);
  border: 1px solid rgba(49, 242, 255, 0.22);
  clip-path: polygon(9px 0, 100% 0, 100% calc(100% - 9px), calc(100% - 9px) 100%, 0 100%, 0 9px);
}
.btn-ghost:hover {
  color: #fff;
  border-color: rgba(49, 242, 255, 0.62);
  background: rgba(49, 242, 255, 0.09);
  box-shadow: 0 0 22px rgba(49, 242, 255, 0.16);
}

.menu-controls {
  display: grid;
  gap: 8px;
  margin-top: 16px;
  padding-top: 14px;
  border-top: 1px solid rgba(49, 242, 255, 0.1);
}
.control-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  font-family: var(--font-display);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: rgba(179, 205, 224, 0.6);
}
.keys { display: flex; align-items: center; gap: 4px; color: rgba(226, 252, 255, 0.9); }
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 21px;
  padding: 0 5px;
  font-family: var(--font-display);
  font-size: 8px;
  font-weight: 700;
  color: rgba(219, 252, 255, 0.9);
  background: rgba(49, 242, 255, 0.06);
  border: 1px solid rgba(49, 242, 255, 0.24);
  border-radius: 2px;
  box-shadow: inset 0 -2px 0 rgba(49, 242, 255, 0.12);
}
.or { margin: 0 3px; color: rgba(255, 43, 204, 0.55); font-size: 8px; }
.menu-tip {
  display: flex;
  align-items: center;
  gap: 9px;
  margin-top: 14px;
  padding: 9px 11px;
  font-family: var(--font-display);
  font-size: 7.5px;
  letter-spacing: 0.16em;
  text-align: left;
  color: rgba(255, 196, 92, 0.78);
  background: rgba(255, 196, 92, 0.045);
  border-left: 2px solid rgba(255, 196, 92, 0.5);
}
.tip-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 15px;
  height: 15px;
  font-size: 9px;
  color: #160c00;
  background: var(--amber);
  border-radius: 50%;
  box-shadow: 0 0 10px rgba(255, 196, 92, 0.55);
}

.menu-footer {
  position: absolute;
  left: clamp(18px, 3vw, 46px);
  right: clamp(18px, 3vw, 46px);
  bottom: calc(18px + var(--safe-bottom));
  z-index: 1;
  display: flex;
  justify-content: space-between;
  gap: 20px;
  font-family: var(--font-display);
  font-size: 7px;
  letter-spacing: 0.2em;
  color: rgba(129, 160, 189, 0.4);
}
.footer-sound { color: rgba(255, 43, 204, 0.34); }

/* Pause / game over */

.screen-scrim {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 55% 55% at 50% 50%, rgba(10, 2, 27, 0.54), rgba(3, 0, 10, 0.88)),
    repeating-linear-gradient(to bottom, transparent 0 3px, rgba(255, 255, 255, 0.016) 3px 4px);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}

.panel {
  position: relative;
  z-index: 1;
  width: min(460px, 92vw);
  padding: clamp(24px, 3.5vh, 38px) clamp(22px, 3vw, 38px) clamp(20px, 3vh, 28px);
  text-align: center;
  background:
    linear-gradient(155deg, rgba(17, 7, 42, 0.92), rgba(4, 1, 15, 0.94)),
    radial-gradient(ellipse at top, rgba(49, 242, 255, 0.1), transparent 58%);
  border: 1px solid rgba(49, 242, 255, 0.24);
  clip-path: polygon(22px 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%, 0 22px);
  box-shadow:
    0 40px 120px rgba(0, 0, 0, 0.72),
    0 0 90px rgba(49, 242, 255, 0.07),
    inset 0 0 60px rgba(49, 242, 255, 0.035);
  animation: panelIn 380ms cubic-bezier(.16, .84, .28, 1) both;
}
@keyframes panelIn {
  from { opacity: 0; transform: translateY(18px) scale(0.975); }
  to { opacity: 1; transform: none; }
}
.panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 22px;
  right: 22px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(49, 242, 255, 0.72), rgba(255, 43, 204, 0.52), transparent);
}
.panel-title {
  margin: 10px 0 4px;
  font-family: var(--font-display);
  font-weight: 900;
  font-size: clamp(34px, 4.5vw, 54px);
  line-height: 0.9;
  letter-spacing: 0.02em;
  color: #edfeff;
  text-shadow: 0 0 12px rgba(49, 242, 255, 0.55), 0 0 50px rgba(49, 242, 255, 0.24);
  transform: skewX(-4deg);
}
.panel-sub {
  margin: 8px 0 22px;
  font-family: var(--font-display);
  font-size: 8px;
  letter-spacing: 0.24em;
  color: rgba(170, 197, 216, 0.55);
}
.panel-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 0 0 22px;
  padding: 14px 0;
  border-top: 1px solid rgba(49, 242, 255, 0.12);
  border-bottom: 1px solid rgba(49, 242, 255, 0.12);
  background: rgba(49, 242, 255, 0.02);
}
.panel-stats div { display: flex; flex-direction: column; gap: 5px; }
.panel-stats span {
  font-family: var(--font-display);
  font-size: 7px;
  letter-spacing: 0.2em;
  color: rgba(160, 192, 211, 0.55);
}
.panel-stats strong {
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 700;
  color: var(--cyan-hot);
  text-shadow: 0 0 10px rgba(49, 242, 255, 0.45);
}

.panel-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 10px;
}

.panel-footer-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-top: 20px;
  padding-top: 13px;
  border-top: 1px solid rgba(49, 242, 255, 0.08);
}
.panel-code {
