/* Sector / event callouts */

#toast-layer {
  position: absolute;
  top: 21%;
  left: 0;
  right: 0;
  z-index: 35;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  pointer-events: none;
}
.callout {
  position: relative;
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 8px 22px;
  font-family: var(--font-display);
  font-size: clamp(10px, 1.15vw, 15px);
  font-weight: 700;
  letter-spacing: 0.28em;
  color: #051017;
  background: linear-gradient(100deg, #8dfcff, #31f2ff 45%, #ff59d8);
  clip-path: polygon(10px 0, 100% 0, calc(100% - 10px) 100%, 0 100%);
  box-shadow: 0 0 34px rgba(49, 242, 255, 0.45);
  animation: calloutIn 2.2s cubic-bezier(.16, .84, .28, 1) forwards;
}
.callout::before, .callout::after {
  content: '';
  width: 20px;
  height: 1px;
  background: rgba(5, 16, 23, 0.4);
}
.callout.danger {
  color: #fff;
  background: linear-gradient(100deg, #ff8a5c, #ff2bcc 65%, #9d5cff);
  box-shadow: 0 0 34px rgba(255, 43, 204, 0.4);
}
@keyframes calloutIn {
  0% { opacity: 0; transform: scaleX(0.6) translateY(8px); }
  8% { opacity: 1; transform: scaleX(1) translateY(0); }
  78% { opacity: 1; transform: none; }
  100% { opacity: 0; transform: translateY(-10px); }
}

.launch-flash {
  position: absolute;
  inset: 0;
  z-index: 45;
  display: grid;
  place-items: center;
  pointer-events: none;
  opacity: 0;
  background: radial-gradient(ellipse at center, rgba(49, 242, 255, 0.16), transparent 58%);
}
.launch-flash span {
  font-family: var(--font-display);
  font-size: clamp(72px, 14vw, 190px);
  font-weight: 900;
  font-style: italic;
  color: transparent;
  -webkit-text-stroke: 2px rgba(185, 254, 255, 0.8);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.24), rgba(49, 242, 255, 0.02));
  -webkit-background-clip: text;
  background-clip: text;
  text-shadow: 0 0 60px rgba(49, 242, 255, 0.55);
  transform: skewX(-8deg);
}
.launch-flash.fire { animation: launchGo 900ms ease-out forwards; }
@keyframes launchGo {
  0% { opacity: 0; transform: scale(1.28); }
  12% { opacity: 1; }
  32% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; }
}

