// ============================================================
// NEON OVERDRIVE — procedural audio engine
// All sounds are synthesized with WebAudio: no external assets.
// ============================================================

const MUTE_KEY = 'neon-overdrive.muted';

const midi = (n) => 440 * Math.pow(2, (n - 69) / 12);

export class NeonAudio {
  constructor() {
    this.ac = null;
    this.master = null;
    this.sfxBus = null;
    this.musicBus = null;
    this.engineBus = null;
    this.noiseBuffer = null;
    this.engine = null;
    this.wind = null;
    this.nitro = null;
    this.musicTimer = null;
    this.musicStep = 0;
    this.nextNote = 0;
    this.musicWanted = false;
    this.engineOn = false;
    this.muted = false;
    try {
      this.muted = localStorage.getItem(MUTE_KEY) === '1';
    } catch {
      this.muted = false;
    }
  }

  async unlock() {
    if (!this.ac) this.#init();
    if (!this.ac) return;
    if (this.ac.state === 'suspended') {
      try { await this.ac.resume(); } catch { /* gesture still pending */ }
    }
  }

  #init() {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    try {
      const ac = new AC({ latencyHint: 'interactive' });
      this.ac = ac;

      this.master = ac.createGain();
      this.master.gain.value = this.muted ? 0 : 0.72;
      this.master.connect(ac.destination);

      const comp = ac.createDynamicsCompressor();
      comp.threshold.value = -14;
      comp.knee.value = 20;
      comp.ratio.value = 5;
      comp.attack.value = 0.004;
      comp.release.value = 0.2;
      this.master.connect(comp);
      comp.connect(ac.destination);

      this.sfxBus = ac.createGain();
      this.sfxBus.gain.value = 0.9;
      this.sfxBus.connect(this.master);

      this.musicBus = ac.createGain();
      this.musicBus.gain.value = 0.0;
      this.musicBus.connect(this.master);

      this.engineBus = ac.createGain();
      this.engineBus.gain.value = 0.9;
      this.engineBus.connect(this.master);

      const length = Math.floor(ac.sampleRate * 2);
      const buffer = ac.createBuffer(1, length, ac.sampleRate);
      const data = buffer.getChannelData(0);
      let last = 0;
      for (let i = 0; i < length; i++) {
        const white = Math.random() * 2 - 1;
        last = last * 0.6 + white * 0.4;
        data[i] = last;
      }
      this.noiseBuffer = buffer;
    } catch {
      this.ac = null;
    }
  }

  setMuted(muted) {
    this.muted = Boolean(muted);
    try { localStorage.setItem(MUTE_KEY, this.muted ? '1' : '0'); } catch { /* private mode */ }
    if (this.master && this.ac) {
      const t = this.ac.currentTime;
      this.master.gain.cancelScheduledValues(t);
      this.master.gain.setTargetAtTime(this.muted ? 0 : 0.72, t, 0.03);
    }
  }

  toggleMute() {
    this.setMuted(!this.muted);
    if (!this.muted) this.click();
    return this.muted;
  }

  get time() {
    return this.ac ? this.ac.currentTime : 0;
  }

  #noise(duration, { type = 'bandpass', freq = 1000, q = 0.8, gain = 0.2, attack = 0.004 } = {}) {
    if (!this.ac || !this.noiseBuffer) return null;
    const ac = this.ac;
    const src = ac.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    const filter = ac.createBiquadFilter();
    filter.type = type;
    filter.frequency.setValueAtTime(freq, ac.currentTime);
    filter.Q.value = q;
    const g = ac.createGain();
    const t = ac.currentTime;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(gain, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    src.connect(filter);
    filter.connect(g);
    g.connect(this.sfxBus);
    src.start(t);
    src.stop(t + duration + 0.05);
    return { src, filter, gain: g };
  }

  #ping(freq, { duration = 0.12, type = 'sine', gain = 0.16, slide = 1, delay = 0, dest = null } = {}) {
    if (!this.ac) return;
    const ac = this.ac;
    const t0 = ac.currentTime + delay;
    const osc = ac.createOscillator();
    const g = ac.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(30, freq), t0);
    if (slide !== 1) {
      osc.frequency.exponentialRampToValueAtTime(Math.max(25, freq * slide), t0 + duration);
    }
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.linearRampToValueAtTime(gain, t0 + Math.min(0.015, duration * 0.2));
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    osc.connect(g);
    g.connect(dest || this.sfxBus);
    osc.start(t0);
    osc.stop(t0 + duration + 0.03);
  }

  click() {
    this.#ping(240, { duration: 0.055, type: 'square', gain: 0.035, slide: 2.1 });
  }

  start() {
    this.#ping(120, { duration: 0.7, type: 'sawtooth', gain: 0.08, slide: 5 });
    this.#noise(0.65, { type: 'highpass', freq: 300, q: 0.5, gain: 0.05 });
    this.#ping(880, { duration: 0.55, type: 'triangle', gain: 0.07, slide: 1.8, delay: 0.14 });
  }

  countdown(final = false) {
    this.#ping(final ? 1046 : 523, {
      duration: final ? 0.38 : 0.1,
      type: 'square',
      gain: final ? 0.055 : 0.035,
    });
  }

  coin(chain = 1) {
    const base = 920 + Math.min(8, chain) * 55;
    this.#ping(base, { duration: 0.09, type: 'sine', gain: 0.1 });
    this.#ping(base * 1.5, { duration: 0.16, type: 'sine', gain: 0.07, delay: 0.055 });
  }

  orb() {
    this.#ping(320, { duration: 0.32, type: 'triangle', gain: 0.11, slide: 3.3 });
    this.#ping(760, { duration: 0.4, type: 'sine', gain: 0.06, slide: 1.6, delay: 0.03 });
    this.#noise(0.32, { type: 'bandpass', freq: 2600, q: 2, gain: 0.035 });
  }

  surge() {
    this.#ping(180, { duration: 0.6, type: 'sawtooth', gain: 0.09, slide: 5 });
    [523, 659, 784, 1046].forEach((f, i) => {
      this.#ping(f, { duration: 0.5, type: 'triangle', gain: 0.06, delay: i * 0.055 });
    });
  }

  nearMiss() {
    const n = this.#noise(0.38, { type: 'bandpass', freq: 2400, q: 1.4, gain: 0.1 });
    if (n) {
      const t = this.ac.currentTime;
      n.filter.frequency.exponentialRampToValueAtTime(360, t + 0.36);
    }
    this.#ping(1400, { duration: 0.13, type: 'sine', gain: 0.045, slide: 0.65, delay: 0.02 });
  }

  crash() {
    const n = this.#noise(0.55, { type: 'lowpass', freq: 1800, q: 0.7, gain: 0.26 });
    if (n) {
      const t = this.ac.currentTime;
      n.filter.frequency.exponentialRampToValueAtTime(180, t + 0.5);
    }
    this.#ping(120, { duration: 0.45, type: 'sawtooth', gain: 0.2, slide: 0.3 });
    this.#ping(70, { duration: 0.6, type: 'sine', gain: 0.28, slide: 0.55 });
    this.#noise(0.16, { type: 'highpass', freq: 4200, q: 0.7, gain: 0.08 });
  }

  explode() {
    this.#noise(1.2, { type: 'lowpass', freq: 1200, q: 0.5, gain: 0.32, attack: 0.006 });
    this.#ping(90, { duration: 1.1, type: 'sine', gain: 0.3, slide: 0.3 });
    this.#ping(160, { duration: 0.5, type: 'sawtooth', gain: 0.14, slide: 0.2 });
    this.#noise(0.5, { type: 'highpass', freq: 3000, gain: 0.06, attack: 0.15 });
  }

  levelUp() {
    [392, 523, 659, 784].forEach((f, i) => {
      this.#ping(f, { duration: 0.32, type: 'triangle', gain: 0.075, delay: i * 0.06 });
    });
  }

  gameOver() {
    if (!this.ac) return;
    this.stopEngine();
    this.stopMusic();
    this.#ping(330, { duration: 0.9, type: 'sawtooth', gain: 0.09, slide: 0.16 });
    this.#ping(165, { duration: 1.2, type: 'triangle', gain: 0.09, slide: 0.3, delay: 0.08 });
    this.#noise(1.0, { type: 'lowpass', freq: 700, q: 0.6, gain: 0.05, attack: 0.2 });
  }

  highScore() {
    [523, 659, 784, 1046, 1318].forEach((f, i) => {
      this.#ping(f, { duration: 0.5, type: 'triangle', gain: 0.07, delay: i * 0.085 });
    });
  }

  startEngine() {
    if (!this.ac || this.engineOn) return;
    const ac = this.ac;
    this.engineOn = true;

    const gain = ac.createGain();
    gain.gain.value = 0.0001;
    const filter = ac.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 420;
    filter.Q.value = 2.5;

    const o1 = ac.createOscillator();
    o1.type = 'sawtooth';
    o1.frequency.value = 58;
    const o2 = ac.createOscillator();
    o2.type = 'square';
    o2.frequency.value = 87;
    o2.detune.value = 9;
    const o3 = ac.createOscillator();
    o3.type = 'sawtooth';
    o3.frequency.value = 29;
    o3.detune.value = -7;

    const subGain = ac.createGain();
    subGain.gain.value = 0.35;
    const mix = ac.createGain();
    mix.gain.value = 0.5;

    o1.connect(mix);
    o2.connect(mix);
    o3.connect(subGain);
    subGain.connect(mix);
    mix.connect(filter);
    filter.connect(gain);
    gain.connect(this.engineBus);

    o1.start();
    o2.start();
    o3.start();
    gain.gain.setTargetAtTime(0.02, ac.currentTime, 0.15);

    // wind / tyre hiss
    const windSrc = ac.createBufferSource();
    windSrc.buffer = this.noiseBuffer;
    windSrc.loop = true;
    const windFilter = ac.createBiquadFilter();
    windFilter.type = 'bandpass';
    windFilter.frequency.value = 1500;
    windFilter.Q.value = 0.45;
    const windGain = ac.createGain();
    windGain.gain.value = 0.0001;
    windSrc.connect(windFilter);
    windFilter.connect(windGain);
    windGain.connect(this.engineBus);
    windSrc.start();

    // nitro thrust
    const nitroSrc = ac.createBufferSource();
    nitroSrc.buffer = this.noiseBuffer;
    nitroSrc.loop = true;
    const nitroFilter = ac.createBiquadFilter();
    nitroFilter.type = 'bandpass';
    nitroFilter.frequency.value = 850;
    nitroFilter.Q.value = 1.1;
    const nitroGain = ac.createGain();
    nitroGain.gain.value = 0.0001;
    nitroSrc.connect(nitroFilter);
    nitroFilter.connect(nitroGain);
    nitroGain.connect(this.engineBus);
    nitroSrc.start();

    this.engine = {
      gain, filter, o1, o2, o3, windGain, windFilter,
      nitroGain, nitroFilter, nitroSrc, windSrc,
    };
  }

  stopEngine() {
    if (!this.ac || !this.engineOn || !this.engine) return;
    const { gain, o1, o2, o3, windSrc, nitroSrc } = this.engine;
    const t = this.ac.currentTime;
    gain.gain.cancelScheduledValues(t);
    gain.gain.setTargetAtTime(0.0001, t, 0.12);
    try {
      o1.stop(t + 0.5);
      o2.stop(t + 0.5);
      o3.stop(t + 0.5);
      windSrc.stop(t + 0.5);
      nitroSrc.stop(t + 0.5);
    } catch { /* already stopped */ }
    this.engine = null;
    this.engineOn = false;
    this.nitroActive = false;
  }

  setEngine(norm, boost = 0) {
    if (!this.engine || !this.ac) return;
    const t = this.ac.currentTime;
    const e = this.engine;
    const base = 48 + norm * 118 + boost * 34;
    e.o1.frequency.setTargetAtTime(base, t, 0.06);
    e.o2.frequency.setTargetAtTime(base * 1.503, t, 0.06);
    e.o3.frequency.setTargetAtTime(base * 0.5, t, 0.06);
    e.filter.frequency.setTargetAtTime(320 + norm * 720 + boost * 500, t, 0.1);
    e.gain.gain.setTargetAtTime(0.016 + norm * 0.012 + boost * 0.006, t, 0.08);
    e.windGain.gain.setTargetAtTime(0.006 + norm * 0.016, t, 0.12);
    e.windFilter.frequency.setTargetAtTime(900 + norm * 1800, t, 0.1);
  }

  setNitro(active) {
    if (!this.engine || !this.ac) return;
    if (this.nitroActive === active) return;
    this.nitroActive = active;
    const t = this.ac.currentTime;
    this.engine.nitroGain.gain.cancelScheduledValues(t);
    this.engine.nitroGain.gain.setTargetAtTime(active ? 0.065 : 0.0001, t, active ? 0.06 : 0.2);
    this.engine.nitroFilter.frequency.setTargetAtTime(active ? 1400 : 700, t, 0.15);
  }

  startMusic() {
    if (!this.ac || this.musicTimer) return;
    this.musicWanted = true;
    this.musicBus.gain.setTargetAtTime(0.42, this.ac.currentTime, 0.4);
    this.musicStep = 0;
    this.nextNote = this.ac.currentTime + 0.08;
    this.musicTimer = setInterval(() => this.#scheduleMusic(), 60);
    this.#scheduleMusic();
  }

  stopMusic() {
    this.musicWanted = false;
    if (this.musicTimer) {
      clearInterval(this.musicTimer);
      this.musicTimer = null;
    }
    if (this.ac && this.musicBus) {
      this.musicBus.gain.setTargetAtTime(0.0001, this.ac.currentTime, 0.18);
    }
  }

  #scheduleMusic() {
    if (!this.ac || !this.musicWanted) return;
    const stepDur = 60 / 104 / 4;
    while (this.nextNote < this.ac.currentTime + 0.22) {
      this.#musicStep(this.musicStep, this.nextNote, stepDur);
      this.nextNote += stepDur;
      this.musicStep = (this.musicStep + 1) % 64;
    }
  }

  #musicStep(step, time, stepDur) {
    const ac = this.ac;
    const bar = Math.floor(step / 16);
    const inBar = step % 16;
    const roots = [33, 29, 24, 31]; // A1, F1, C1, G1
    const root = roots[bar];
    const dest = this.musicBus;

    const scheduleGain = (gain, attack, hold, release, peak) => {
      gain.gain.setValueAtTime(0.0001, time);
      gain.gain.linearRampToValueAtTime(peak, time + attack);
      gain.gain.setValueAtTime(peak, time + attack + hold);
      gain.gain.exponentialRampToValueAtTime(0.0001, time + attack + hold + release);
    };

    // kick
    if (inBar === 0 || inBar === 6 || inBar === 8 || inBar === 11) {
      const o = ac.createOscillator();
      const g = ac.createGain();
      o.type = 'sine';
      o.frequency.setValueAtTime(130, time);
      o.frequency.exponentialRampToValueAtTime(44, time + 0.15);
      scheduleGain(g, 0.004, 0.02, 0.2, 0.26);
      o.connect(g); g.connect(dest);
      o.start(time); o.stop(time + 0.3);
    }

    // snare
    if (inBar === 4 || inBar === 12) {
      const src = ac.createBufferSource();
      src.buffer = this.noiseBuffer;
      src.loop = true;
      const f = ac.createBiquadFilter();
      f.type = 'bandpass'; f.frequency.value = 1900; f.Q.value = 0.9;
      const g = ac.createGain();
      scheduleGain(g, 0.003, 0.01, 0.14, 0.09);
      src.connect(f); f.connect(g); g.connect(dest);
      src.start(time); src.stop(time + 0.18);
    }

    // hats
    if (inBar % 2 === 0) {
      const src = ac.createBufferSource();
      src.buffer = this.noiseBuffer;
      src.loop = true;
      const f = ac.createBiquadFilter();
      f.type = 'highpass'; f.frequency.value = 7000;
      const g = ac.createGain();
      scheduleGain(g, 0.002, 0.005, inBar % 4 === 0 ? 0.09 : 0.045, 0.035);
      src.connect(f); f.connect(g); g.connect(dest);
      src.start(time); src.stop(time + 0.12);
    }

    // bass pulse
    if ([0, 3, 6, 8, 11, 14].includes(inBar)) {
      const o = ac.createOscillator();
      const f = ac.createBiquadFilter();
      const g = ac.createGain();
      o.type = 'sawtooth';
      const note = root + (inBar === 8 ? 12 : 0);
      o.frequency.value = midi(note + 12);
      f.type = 'lowpass';
      f.frequency.setValueAtTime(260, time);
      f.frequency.exponentialRampToValueAtTime(1100, time + 0.05);
      f.frequency.exponentialRampToValueAtTime(240, time + 0.19);
      f.Q.value = 4;
      scheduleGain(g, 0.005, 0.03, 0.16, 0.075);
      o.connect(f); f.connect(g); g.connect(dest);
      o.start(time); o.stop(time + 0.22);
    }

    // arp
    if (inBar % 2 === 0) {
      const notes = [0, 7, 12, 15, 7, 19, 15, 12];
      const chord = [0, 3, 7, 10];
      const rel = notes[(inBar / 2) % notes.length] + chord[bar];
      const o = ac.createOscillator();
      const g = ac.createGain();
      o.type = 'triangle';
      o.frequency.value = midi(root + 36 + rel);
      scheduleGain(g, 0.004, 0.01, 0.13, 0.022);
      o.connect(g); g.connect(dest);
      o.start(time); o.stop(time + 0.18);
    }

    // warm pad at bar start
    if (inBar === 0) {
      const chord = bar === 0 ? [0, 3, 7] : bar === 1 ? [0, 4, 7] : bar === 2 ? [0, 4, 7] : [0, 4, 7];
      chord.forEach((iv, i) => {
        const o = ac.createOscillator();
        const f = ac.createBiquadFilter();
        const g = ac.createGain();
        o.type = 'sawtooth';
        o.frequency.value = midi(root + 24 + iv);
        o.detune.value = (i - 1) * 6;
        f.type = 'lowpass';
        f.frequency.value = 1100;
        g.gain.setValueAtTime(0.0001, time);
        g.gain.linearRampToValueAtTime(0.007, time + 0.35);
        g.gain.setValueAtTime(0.007, time + 1.4);
        g.gain.exponentialRampToValueAtTime(0.0001, time + 2.25);
        o.connect(f); f.connect(g); g.connect(dest);
        o.start(time); o.stop(time + 2.4);
      });
    }
  }
}

// ============================================================
// NEON OVERDRIVE — procedural sprite art
// Everything is drawn at boot into cached canvases so the game
// loop only pays for a handful of scaled drawImage calls.
// ============================================================

const SS = 2.4;

function sprite(w, h, draw, scale = SS) {
  const canvas = document.createElement('canvas');
  canvas.width = Math.ceil(w * scale);
  canvas.height = Math.ceil(h * scale);
  const g = canvas.getContext('2d');
  g.scale(scale, scale);
  g.lineJoin = 'round';
  g.lineCap = 'round';
  draw(g, w, h);
  return { canvas, w, h };
}

function roundRect(g, x, y, w, h, r) {
  const radius = Math.min(r, w / 2, h / 2);
  g.beginPath();
  g.moveTo(x + radius, y);
  g.arcTo(x + w, y, x + w, y + h, radius);
  g.arcTo(x + w, y + h, x, y + h, radius);
  g.arcTo(x, y + h, x, y, radius);
  g.arcTo(x, y, x + w, y, radius);
  g.closePath();
}

function hexRgb(hex) {
  const v = hex.replace('#', '');
  const n = v.length === 3 ? v.split('').map(c => c + c).join('') : v;
  return [parseInt(n.slice(0, 2), 16), parseInt(n.slice(2, 4), 16), parseInt(n.slice(4, 6), 16)];
}

export function rgba(hex, alpha) {
  const [r, g, b] = hexRgb(hex);
  return `rgba(${r},${g},${b},${alpha})`;
}

export function mix(hex, target, amount) {
  const a = hexRgb(hex);
  const b = hexRgb(target);
  return `rgb(${Math.round(a.map((v, i) => v + (b[i] - v) * amount).join(','))})`;
}

function vGrad(g, y0, y1, stops) {
  const grad = g.createLinearGradient(0, y0, 0, y1);
  stops.forEach(([at, color]) => grad.addColorStop(at, color));
  return grad;
}

// ------------------------------------------------------------
// Player hypercar
// ------------------------------------------------------------

export function createPlayerSprite() {
  return sprite(210, 400, (g, w, h) => {
    const cx = w / 2;

    // ground shadow baked softly under the car
    g.save();
    g.translate(cx, 372);
    g.scale(1, 0.28);
    const sh = g.createRadialGradient(0, 0, 4, 0, 0, 82);
    sh.addColorStop(0, 'rgba(0,0,0,0.62)');
    sh.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = sh;
    g.beginPath(); g.arc(0, 0, 82, 0, Math.PI * 2); g.fill();
    g.restore();

    // wheels
    const wheel = (x, y, ww, hh) => {
      g.fillStyle = '#06040e';
      roundRect(g, x, y, ww, hh, 7);
      g.fill();
      g.strokeStyle = 'rgba(72, 96, 140, 0.55)';
      g.lineWidth = 1.2;
      g.stroke();
      g.fillStyle = 'rgba(18, 26, 50, 0.95)';
      roundRect(g, x + 3, y + 5, ww - 6, hh - 10, 5);
      g.fill();
      // glowing rim line
      g.strokeStyle = 'rgba(49,242,255,0.6)';
      g.lineWidth = 1.4;
      g.beginPath();
      g.moveTo(x + 2, y + 9);
      g.lineTo(x + 2, y + hh - 9);
      g.stroke();
    };
    wheel(39, 84, 22, 54);
    wheel(149, 84, 22, 54);
    wheel(35, 260, 26, 62);
    wheel(149, 260, 26, 62);

    // rear diffuser fins
    g.strokeStyle = 'rgba(42, 20, 76, 0.9)';
    g.lineWidth = 3;
    for (let i = 0; i < 5; i++) {
      const x = 70 + i * 17;
      g.beginPath(); g.moveTo(x, 344); g.lineTo(x, 368); g.stroke();
    }

    // main body
    const body = new Path2D();
    body.moveTo(cx, 26);
    body.bezierCurveTo(cx + 16, 26, cx + 29, 48, cx + 34, 80);
    body.bezierCurveTo(cx + 40, 108, cx + 53, 139, cx + 55, 185);
    body.bezierCurveTo(cx + 57, 232, cx + 55, 292, cx + 50, 335);
    body.bezierCurveTo(cx + 47, 360, cx + 35, 373, cx + 20, 377);
    body.lineTo(cx - 20, 377);
    body.bezierCurveTo(cx - 35, 373, cx - 47, 360, cx - 50, 335);
    body.bezierCurveTo(cx - 55, 292, cx - 57, 232, cx - 55, 185);
    body.bezierCurveTo(cx - 53, 139, cx - 40, 108, cx - 34, 80);
    body.bezierCurveTo(cx - 29, 48, cx - 16, 26, cx, 26);
    body.closePath();

    g.save();
    g.shadowColor = 'rgba(49,242,255,0.75)';
    g.shadowBlur = 16;
    g.fillStyle = vGrad(g, 20, 380, [
      [0, '#f7ffff'],
      [0.09, '#d7fcff'],
      [0.22, '#8ceaff'],
      [0.38, '#46b7ff'],
      [0.55, '#2c6ce6'],
      [0.72, '#27228f'],
      [0.88, '#1b0c48'],
      [1, '#10052c'],
    ]);
    g.fill(body);
    g.restore();

    // side shading
    g.save();
    g.clip(body);
    const sideL = g.createLinearGradient(50, 0, cx, 0);
    sideL.addColorStop(0, 'rgba(3, 5, 22, 0.72)');
    sideL.addColorStop(0.28, 'rgba(6, 16, 44, 0.16)');
    sideL.addColorStop(0.55, 'rgba(255,255,255,0.08)');
    sideL.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = sideL;
    g.fillRect(40, 20, cx - 40, 370);
    const sideR = g.createLinearGradient(w - 50, 0, cx, 0);
    sideR.addColorStop(0, 'rgba(3, 5, 22, 0.72)');
    sideR.addColorStop(0.28, 'rgba(6, 16, 44, 0.16)');
    sideR.addColorStop(0.55, 'rgba(255,255,255,0.08)');
    sideR.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = sideR;
    g.fillRect(cx, 20, w - cx - 40, 370);

    // rear heat haze / body vents
    const vent = g.createLinearGradient(0, 300, 0, 370);
    vent.addColorStop(0, 'rgba(5, 4, 20, 0)');
    vent.addColorStop(1, 'rgba(3, 2, 14, 0.75)');
    g.fillStyle = vent;
    g.fillRect(50, 295, w - 100, 82);
    g.restore();

    // body outline
    g.strokeStyle = 'rgba(197, 254, 255, 0.92)';
    g.lineWidth = 2.2;
    g.stroke(body);
    g.strokeStyle = 'rgba(49, 242, 255, 0.5)';
    g.lineWidth = 5;
    g.globalAlpha = 0.35;
    g.stroke(body);
    g.globalAlpha = 1;

    // nose intakes
    g.fillStyle = 'rgba(2, 8, 22, 0.86)';
    g.beginPath();
    g.moveTo(cx - 24, 64); g.lineTo(cx - 12, 50); g.lineTo(cx - 9, 86); g.lineTo(cx - 22, 92);
    g.closePath(); g.fill();
    g.beginPath();
    g.moveTo(cx + 24, 64); g.lineTo(cx + 12, 50); g.lineTo(cx + 9, 86); g.lineTo(cx + 22, 92);
    g.closePath(); g.fill();

    // headlight slits
    const head = (x) => {
      const hg = g.createLinearGradient(0, 40, 0, 60);
      hg.addColorStop(0, '#ffffff');
      hg.addColorStop(0.45, '#b7feff');
      hg.addColorStop(1, '#25baff');
      g.fillStyle = hg;
      g.beginPath();
      g.moveTo(x, 48); g.lineTo(x + 14, 55); g.lineTo(x + 10, 65); g.lineTo(x - 4, 56);
      g.closePath(); g.fill();
    };
    head(cx - 31);
    head(cx + 17);

    // center racing stripe
    const stripe = g.createLinearGradient(0, 30, 0, 330);
    stripe.addColorStop(0, 'rgba(255,255,255,0.9)');
    stripe.addColorStop(0.4, 'rgba(255,255,255,0.55)');
    stripe.addColorStop(0.7, 'rgba(255,255,255,0.08)');
    stripe.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = stripe;
    g.beginPath();
    g.moveTo(cx - 5, 34);
    g.lineTo(cx + 5, 34);
    g.lineTo(cx + 9, 124);
    g.lineTo(cx + 3, 198);
    g.lineTo(cx - 3, 198);
    g.lineTo(cx - 9, 124);
    g.closePath();
    g.fill();

    // cockpit
    const cockpit = new Path2D();
    cockpit.moveTo(cx, 118);
    cockpit.bezierCurveTo(cx + 19, 120, cx + 26, 146, cx + 27, 180);
    cockpit.bezierCurveTo(cx + 27, 208, cx + 17, 228, cx, 236);
    cockpit.bezierCurveTo(cx - 17, 228, cx - 27, 208, cx - 27, 180);
    cockpit.bezierCurveTo(cx - 26, 146, cx - 19, 120, cx, 118);
    cockpit.closePath();
    const cockpitGrad = g.createLinearGradient(0, 118, 0, 236);
    cockpitGrad.addColorStop(0, '#0b2942');
    cockpitGrad.addColorStop(0.4, '#051327');
    cockpitGrad.addColorStop(1, '#020712');
    g.fillStyle = cockpitGrad;
    g.fill(cockpit);
    g.strokeStyle = 'rgba(49,242,255,0.65)';
    g.lineWidth = 1.5;
    g.stroke(cockpit);

    // windshield reflection
    g.save();
    g.clip(cockpit);
    g.globalAlpha = 0.4;
    g.fillStyle = 'rgba(140, 245, 255, 0.55)';
    g.beginPath();
    g.moveTo(cx - 18, 128);
    g.lineTo(cx + 2, 136);
    g.lineTo(cx - 12, 183);
    g.lineTo(cx - 25, 165);
    g.closePath();
    g.fill();
    g.globalAlpha = 0.18;
    g.fillStyle = '#ff2bcc';
    g.fillRect(cx - 30, 200, 60, 8);
    g.restore();

    // cockpit halo frame
    g.strokeStyle = 'rgba(185,254,255,0.35)';
    g.lineWidth = 3.5;
    g.beginPath();
    g.moveTo(cx - 30, 188);
    g.bezierCurveTo(cx - 30, 226, cx - 18, 241, cx, 245);
    g.bezierCurveTo(cx + 18, 241, cx + 30, 226, cx + 30, 188);
    g.stroke();

    // side neon light strips
    const strip = (side) => {
      const x = side < 0 ? 61 : 149;
      g.save();
      g.strokeStyle = 'rgba(255,43,204,0.95)';
      g.shadowColor = '#ff2bcc';
      g.shadowBlur = 12;
      g.lineWidth = 3;
      g.beginPath();
      g.moveTo(x + side * 3, 116);
      g.quadraticCurveTo(x + side * 6, 200, x + side * 5, 300);
      g.stroke();
      g.restore();
      g.strokeStyle = 'rgba(185,254,255,0.9)';
      g.lineWidth = 1;
      g.beginPath();
      g.moveTo(x + side * 4, 120);
      g.quadraticCurveTo(x + side * 7, 200, x + side * 6, 294);
      g.stroke();
    };
    strip(-1);
    strip(1);

    // rear wing
    const wing = g.createLinearGradient(0, 328, 0, 352);
    wing.addColorStop(0, '#ff86e8');
    wing.addColorStop(0.4, '#b42cff');
    wing.addColorStop(1, '#3a0b6e');
    g.fillStyle = wing;
    roundRect(g, 47, 328, w - 94, 15, 4);
    g.fill();
    g.strokeStyle = 'rgba(255,175,240,0.9)';
    g.lineWidth = 1.4;
    g.stroke();
    g.fillStyle = 'rgba(6,3,18,0.9)';
    roundRect(g, 60, 343, 13, 14, 3); g.fill();
    roundRect(g, w - 73, 343, 13, 14, 3); g.fill();
    g.fillStyle = 'rgba(49,242,255,0.9)';
    g.fillRect(74, 333, 20, 2);
    g.fillRect(w - 94, 333, 20, 2);

    // thruster housings
    const thruster = (x) => {
      g.save();
      g.translate(x, 366);
      g.fillStyle = '#09041a';
      g.beginPath(); g.ellipse(0, 0, 13, 10, 0, 0, Math.PI * 2); g.fill();
      const core = g.createRadialGradient(0, 0, 1, 0, 0, 10);
      core.addColorStop(0, '#ffffff');
      core.addColorStop(0.35, '#8ffcff');
      core.addColorStop(0.7, '#20b8ff');
      core.addColorStop(1, '#6a24ff');
      g.fillStyle = core;
      g.beginPath(); g.ellipse(0, 0, 8, 6.5, 0, 0, Math.PI * 2); g.fill();
      g.strokeStyle = 'rgba(255,43,204,0.85)';
      g.lineWidth = 1.5;
      g.beginPath(); g.ellipse(0, 0, 12, 9, 0, 0, Math.PI * 2); g.stroke();
      g.restore();
    };
    thruster(cx - 21);
    thruster(cx + 21);

    // tail light bar
    g.save();
    g.shadowColor = '#ff2bcc';
    g.shadowBlur = 16;
    g.fillStyle = 'rgba(255, 60, 210, 0.95)';
    roundRect(g, 70, 349, w - 140, 4, 2);
    g.fill();
    g.restore();

    // small hood decal
    g.fillStyle = 'rgba(6, 12, 30, 0.9)';
    g.font = '700 13px Orbitron, sans-serif';
    g.textAlign = 'center';
    g.fillText('07', cx, 104);
    g.fillStyle = 'rgba(185,254,255,0.65)';
    g.font = '700 6px Orbitron, sans-serif';
    g.fillText('NX-09', cx, 112);

    // panel seams
    g.strokeStyle = 'rgba(7, 18, 40, 0.55)';
    g.lineWidth = 1;
    g.beginPath();
    g.moveTo(cx - 38, 255); g.lineTo(cx - 8, 262);
    g.moveTo(cx + 38, 255); g.lineTo(cx + 8, 262);
    g.stroke();
  }, 2.6);
}

// ------------------------------------------------------------
// Traffic vehicles
// ------------------------------------------------------------

const TRAFFIC_META = {
  coupe: { w: 176, h: 320 },
  hover: { w: 168, h: 296 },
  truck: { w: 190, h: 380 },
  bike: { w: 96, h: 238 },
};

export function createTrafficSprite(kind, color) {
  const meta = TRAFFIC_META[kind] || TRAFFIC_META.coupe;
  const W = meta.w;
  const H = meta.h;
  const cx = W / 2;

  return sprite(W, H, (g) => {
    const dark = mix(color, '#05010f', 0.62);
    const mid = mix(color, '#05010f', 0.35);
    const light = mix(color, '#ffffff', 0.35);

    // body shadow
    g.save();
    g.translate(cx, H - 16);
    g.scale(1, 0.3);
    const sh = g.createRadialGradient(0, 0, 4, 0, 0, W * 0.44);
    sh.addColorStop(0, 'rgba(0,0,0,0.55)');
    sh.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = sh;
    g.beginPath(); g.arc(0, 0, W * 0.44, 0, Math.PI * 2); g.fill();
    g.restore();

    if (kind === 'bike') {
      drawBike(g, W, H, cx, color, dark, light);
    } else if (kind === 'truck') {
      drawTruck(g, W, H, cx, color, dark, mid, light);
    } else if (kind === 'hover') {
      drawHover(g, W, H, cx, color, dark, mid, light);
    } else {
      drawCoupe(g, W, H, cx, color, dark, mid, light);
    }
  }, 2.2);
}

function tailLights(g, x, y, w, h, color) {
  g.save();
  g.shadowColor = '#ff1f4c';
  g.shadowBlur = 14;
  g.fillStyle = 'rgba(255, 56, 72, 0.98)';
  roundRect(g, x, y, w, h, 2);
  g.fill();
  g.restore();
  g.fillStyle = 'rgba(255, 220, 230, 0.9)';
  roundRect(g, x + w * 0.15, y + h * 0.28, w * 0.7, Math.max(1, h * 0.3), 1);
  g.fill();
  // colored accent around the tail bar
  g.strokeStyle = rgba(color, 0.75);
  g.lineWidth = 1;
  g.strokeRect(x - 2, y - 2, w + 4, h + 4);
}

function drawCoupe(g, W, H, cx, color, dark, mid, light) {
  // wheels
  const wheel = (x, y, ww, hh) => {
