  }
  g.strokeStyle = 'rgba(4, 6, 18, 0.65)';
  g.lineWidth = 4;
  g.beginPath(); g.moveTo(cx, 118); g.lineTo(cx, H - 34); g.stroke();

  // neon side rails
  g.save();
  g.shadowColor = color;
