  // hazard chevrons at rear
  g.save();
  g.strokeStyle = 'rgba(255, 196, 92, 0.85)';
  g.lineWidth = 3;
  for (let i = 0; i < 3; i++) {
    const y = H - 78 + i * 12;
    g.beginPath();
    g.moveTo(cx - 34, y); g.lineTo(cx, y + 9); g.lineTo(cx + 34, y);
