  g.lineWidth = 1.8;
  g.stroke(body);

  // canopy
  const canopy = new Path2D();
  canopy.moveTo(cx, 82);
  canopy.bezierCurveTo(cx + 26, 92, cx + 33, 140, cx + 27, 190);
  canopy.bezierCurveTo(cx + 21, 226, cx - 21, 226, cx - 27, 190);
  canopy.bezierCurveTo(cx - 33, 140, cx - 26, 92, cx, 82);
