+    this.nitro = Math.min(100, this.nitro + 9);
+    this.player.vx += Math.sign(this.player.x - car.x || 1) * 0.9;
+    this.addFloat('HULL -34', p.x, p.y - 50, '#ff3d6e', 18);
+    this.spawnBurst(p.x, p.y - 20, {
+      count: 40,
