+
+    if (this.hull <= 0) {
+      this.#beginDeath();
+    } else {
+      this.showCallout(`HULL ${Math.round(this.hull)}% // IMPACT`, true);
+    }
+  }
+
+  #beginDeath() {
+    if (this.state !== 'playing') return;
+    this.#setState('dying');
+    this.player.dead = true;
+    this.deathTimer = 0;
+    this.speed = Math.min(this.speed, 48);
+    this.boosting = false;
+    this.boostVisual = 1;
+    this.shake = 36;
+    this.hitFlash = 1;
