// ============================================================
// NEON OVERDRIVE — boot
// ============================================================

import { Game } from './game.js';

const root = document.getElementById('game');
const boot = document.getElementById('boot-flash');

async function waitForFonts() {
  if (!document.fonts || !document.fonts.ready) return;
  try {
    await Promise.race([
      Promise.all([
        document.fonts.load('700 1em Orbitron'),
        document.fonts.load('600 1em Rajdhani'),
        document.fonts.load('500 1em Rajdhani'),
      ]),
      new Promise((resolve) => setTimeout(resolve, 1200)),
    ]);
  } catch {
    /* fonts are optional — proceed regardless */
  }
}

async function bootGame() {
  await waitForFonts();

  const game = new Game(root);
  window.__NEON__ = game;
  window.__NEON_READY__ = true;

  if (boot) {
    boot.classList.add('done');
    window.setTimeout(() => boot.remove(), 900);
  }
}

bootGame();

