// ----------------------------------------------------------
// Background & road rendering
// ----------------------------------------------------------

drawBackground(ctx) {
  const w = this.w;
  const h = this.h;

  ctx.fillStyle = this.skyGrad;
  ctx.fillRect(-40, -40, w + 80, this.horizonY + 80);

  // atmospheric nebula
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.globalAlpha = 0.26;
  ctx.drawImage(this.glows.violet, w * 0.08 - w * 0.3, -h * 0.05, w * 0.6, h * 0.55);
  ctx.globalAlpha = 0.14;
  ctx.drawImage(this.glows.magenta, w * 0.58 - w * 0.25, h * 0.02, w * 0.55, h * 0.5);
  ctx.globalAlpha = 0.16;
  ctx.drawImage(this.glows.cyan, w * 0.38 - w * 0.3, this.horizonY - h * 0.24, w * 0.65, h * 0.35);
  ctx.restore();

  // stars
  const t = this.time;
  for (const star of this.stars) {
    const twinkle = 0.35 + 0.55 * (0.5 + 0.5 * Math.sin(t * star.speed + star.phase));
    ctx.globalAlpha = twinkle;
    ctx.fillStyle = GLOW_COLORS[star.tint] || '#cfefff';
