    grad.addColorStop(1, 'rgba(49,242,255,0)');
    ctx.strokeStyle = grad;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(m.x, m.y);
    ctx.lineTo(m.x - m.vx * 0.16, m.y - m.vy * 0.16);
    ctx.stroke();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(m.x, m.y, 1.8, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

