  this.#drawSkylineLayer(ctx, this.skyNear, this.horizonY + 38, 1);

  // ground base
  ctx.fillStyle = this.groundGrad;
  ctx.fillRect(-40, this.horizonY, w + 80, h - this.horizonY + 40);

  // horizon haze
  ctx.fillStyle = this.hazeGrad;
  ctx.fillRect(-40, this.horizonY - 70, w + 80, 160);

