  hg.addColorStop(0.45, 'rgba(255,138,232,0.5)');
  hg.addColorStop(0.7, 'rgba(49,242,255,0.35)');
  hg.addColorStop(1, 'rgba(49,242,255,0)');
  ctx.fillStyle = hg;
  ctx.fillRect(-40, this.horizonY - 2, w + 80, 14);
}

