drawGroundGrid(ctx) {
  const off = this.distance % 9;
  ctx.save();
  ctx.lineWidth = 1;
  for (let z = off; z < VIEW_DIST; z += 9) {
    const p = this.project(z, 0);
    if (p.y < this.horizonY || p.y > this.h + 4) continue;
    const a = 0.025 + p.s * 0.055;
    ctx.strokeStyle = `rgba(128, 88, 230, ${a.toFixed(3)})`;
    ctx.beginPath();
    ctx.moveTo(-30, p.y);
    ctx.lineTo(this.w + 30, p.y);
    ctx.stroke();
  }

  ctx.strokeStyle = 'rgba(102, 66, 190, 0.055)';
  for (const gx of [-5.4, -4.2, -3.2, -2.4, 2.4, 3.2, 4.2, 5.4]) {
    ctx.beginPath();
    for (let i = 0; i <= 12; i++) {
      const z = (i / 12) * VIEW_DIST;
      const p = this.project(z, gx);
      if (i === 0) ctx.moveTo(p.x, p.y);
      else ctx.lineTo(p.x, p.y);
    }
    ctx.stroke();
  }
  ctx.restore();
}

